// Presentation/focus only. Audio, purchases and the five-second preview stay in run.js.
const sessions=new WeakMap(),attributes=['data-record-filter','data-record-preview','data-record'];
export function applyRebrandRecords(dialog,active=true){
 let state=sessions.get(dialog);if(!active||!dialog.querySelector('.r2-records')){if(state){state.epoch++;dialog.removeEventListener('focusin',state.focus);dialog.removeEventListener('close',state.close);sessions.delete(dialog);}return false;}
 const previous=state&&dialog.open&&dialog.dataset.r2Screen==='records'?state.key:null;
 dialog.classList.add('gv-r2');dialog.classList.remove('bosque-ui','gv-expedition-theme');delete dialog.dataset.gvui;delete dialog.dataset.gvExpedition;dialog.dataset.r2Screen='records';const label=dialog.querySelector('#dialogLabel');if(label)label.textContent='Vitrola';
 if(!state){state={epoch:0,key:null};state.focus=event=>{const b=event.target?.closest?.('button'),attribute=attributes.find(a=>b?.hasAttribute(a));if(dialog.querySelector('.r2-records')?.contains(event.target))state.key=b&&attribute?{attribute,value:b.getAttribute(attribute)}:null;};state.close=()=>{if(!dialog.open){state.epoch++;state.key=null;}};dialog.addEventListener('focusin',state.focus);dialog.addEventListener('close',state.close);sessions.set(dialog,state);}
 const epoch=++state.epoch;if(previous)queueMicrotask(()=>{if(state.epoch!==epoch||state.key!==previous||!dialog.open||!dialog.isConnected||dialog.dataset.r2Screen!=='records')return;const current=dialog.ownerDocument.activeElement,body=dialog.querySelector('#dialogBody');if(current?.isConnected&&current!==dialog.ownerDocument.body&&current!==dialog&&!body?.contains(current))return;const match=attribute=>[...body.querySelectorAll('['+attribute+']')].find(b=>b.getAttribute(attribute)===previous.value);const button=match(previous.attribute),target=button&&!button.disabled?button:previous.attribute==='data-record'?match('data-record-title'):body.querySelector('#currentRecordTitle');if(target){target.focus({preventScroll:true});target.scrollIntoView?.({block:'nearest',inline:'nearest',behavior:'instant'});}});return true;
}
